class Solution {
public:
    int countElements(vector<int>& arr) {
        unordered_set<int> s(arr.begin(), arr.end());
        int ans = 0;
        for (int x : arr) {
            if (s.count(x + 1)) ans++;
        }
        return ans;
    }
};

class Solution {
    public int countElements(int[] arr) {
        Set<Integer> s = new HashSet<>();
        for (int x : arr) s.add(x);
        int ans = 0;
        for (int x : arr) {
            if (s.contains(x + 1)) ans++;
        }
        return ans;
    }
}

var countElements = function(arr) {
    const s = new Set(arr);
    let ans = 0;
    for (const x of arr) {
        if (s.has(x + 1)) ans++;
    }
    return ans;
};
